/* @lc app=leetcode id=3092 lang=kotlin */ class Solution { fun mostFrequentIDs(nums: IntArray, freq: IntArray): LongArray = HashMap<Int, Long>().let { c -> java.util.TreeMap<Long, Int>().let { fc -> nums.indices.map { i -> c.merge(nums[i], freq[i].toLong()) { a, b -> a + b }!!.let { nw -> (nw - freq[i]).let { old -> (if (old > 0) fc.merge(old, -1) { a, b -> a + b }.also { if (it == 0) fc.remove(old) } else null).let { (if (nw > 0) fc.merge(nw, 1) { a, b -> a + b } else null).let { if (fc.isEmpty()) 0L else fc.lastKey() } } } } }.toLongArray() } } }